    const initialPath = getStartPath(json, selection);
    const selectionStartIndex = items.findIndex((item) => isEqual(item.path, initialPath));
    const { offset } = onMoveSelection({
        json,
        selection: context.getSelection(),
        deltaY: 0,
        items
